import{_ as a,c as t,o as r,aj as i}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse(`{"title":"KitchenRatio Calculator","description":"Learn how to use the KitchenRatio calculator to scale doughs with baker's percentages.","frontmatter":{"title":"KitchenRatio Calculator","description":"Learn how to use the KitchenRatio calculator to scale doughs with baker's percentages.","head":[["meta",{"name":"description","content":"Learn how to use the KitchenRatio calculator to scale doughs with baker's percentages."}],["meta",{"property":"og:title","content":"KitchenRatio Calculator"}],["meta",{"property":"og:description","content":"Learn how to use the KitchenRatio calculator to scale doughs with baker's percentages."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/kitchenratio-calculator.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"KitchenRatio Calculator"}],["meta",{"name":"twitter:description","content":"Learn how to use the KitchenRatio calculator to scale doughs with baker's percentages."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/kitchenratio-calculator.html"}]]},"headers":[],"relativePath":"guides/kitchenratio-calculator.md","filePath":"guides/kitchenratio-calculator.md"}`),o={name:"guides/kitchenratio-calculator.md"};function l(s,e,n,h,c,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="kitchenratio-calculator" tabindex="-1">KitchenRatio Calculator <a class="header-anchor" href="#kitchenratio-calculator" aria-label="Permalink to “KitchenRatio Calculator”">​</a></h1><p>The KitchenRatio calculator scales doughs with baker&#39;s percentages, fast. You set the ratio once, then move the flour and everything updates. No napkin math, no mystery. Access it at <a href="https://kitchenratio.com/calculator" target="_blank" rel="noreferrer">https://kitchenratio.com/calculator</a>.</p><h2 id="presets-start-smart-then-tweak" tabindex="-1">Presets (Start Smart, Then Tweak) <a class="header-anchor" href="#presets-start-smart-then-tweak" aria-label="Permalink to “Presets (Start Smart, Then Tweak)”">​</a></h2><p>Presets give you a reliable baseline for breads, pizza, and flatbreads. Pick one, then adjust flour to scale and sliders to dial it in. You get a proven ratio without the guesswork, and you can still make it yours.</p><h2 id="quick-start-the-30-second-tour" tabindex="-1">Quick Start (The 30-Second Tour) <a class="header-anchor" href="#quick-start-the-30-second-tour" aria-label="Permalink to “Quick Start (The 30-Second Tour)”">​</a></h2><ol><li>Set flour with the +/- buttons in the Flour card. That is your 100%.</li><li>Adjust water, salt, and yeast with the sliders.</li><li>Use Add Ingredient for enrichments and other add-ins.</li><li>Read the grams and bake.</li></ol><h2 id="how-the-cards-work" tabindex="-1">How the Cards Work <a class="header-anchor" href="#how-the-cards-work" aria-label="Permalink to “How the Cards Work”">​</a></h2><ul><li><strong>Flour</strong> uses step buttons to scale the batch.</li><li><strong>Water, salt, yeast</strong> use sliders to set percentages.</li><li><strong>Add Ingredient</strong> opens a grouped menu for eggs, dairy, fats, sugars, starches, seeds, and misc.</li><li>Each card shows grams so you can confirm the batch at a glance.</li></ul><h2 id="ratios-that-behave" tabindex="-1">Ratios That Behave <a class="header-anchor" href="#ratios-that-behave" aria-label="Permalink to “Ratios That Behave”">​</a></h2><p>Set the ratio first, then scale the flour.</p><ul><li><strong>Hydration (water %)</strong> controls softness and handling.</li><li><strong>Salt %</strong> shapes flavor and fermentation.</li><li><strong>Yeast %</strong> controls rise speed.</li></ul><p>Lean dough example: <strong>65% water, 2% salt, 0.5% yeast</strong>.</p><h2 id="why-grams" tabindex="-1">Why Grams? <a class="header-anchor" href="#why-grams" aria-label="Permalink to “Why Grams?”">​</a></h2><p>Because grams remove guesswork.</p><ul><li>Cups and tablespoons are volume, and volume changes with scooping style, flour density, and humidity.</li><li>Grams are weight, so the same number gives you the same dough behavior every time.</li><li>Baker&#39;s percentages are weight-based, so grams make the calculator accurate by default.</li></ul><p>If you want repeatable results, grams are not &quot;extra precise&quot; - they are the baseline.</p><h2 id="scaling-workflow-repeatable-and-boring-in-a-good-way" tabindex="-1">Scaling Workflow (Repeatable and Boring, in a Good Way) <a class="header-anchor" href="#scaling-workflow-repeatable-and-boring-in-a-good-way" aria-label="Permalink to “Scaling Workflow (Repeatable and Boring, in a Good Way)”">​</a></h2><ol><li>Dial in a dough you trust.</li><li>Keep the sliders steady.</li><li>Increase or decrease flour to scale the batch.</li></ol><p>Everything else follows automatically.</p><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Weigh in grams for accuracy.</li><li>Add enrichments as percentages of flour (oil, sugar, dairy, eggs).</li><li>Use presets when you want a baseline, then tweak.</li><li>Pair this with <a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a> to understand the &quot;why.&quot;</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/calculator-for-recipes.html">Convert Recipes with the Calculator</a></li><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/yield-planner.html">Yield Planner</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul>',25)])])}const p=a(o,[["render",l]]);export{g as __pageData,p as default};
